'use client';
import React,{FormEvent,useEffect,useState} from 'react';
import Link from 'next/link';
import {Activity,ArrowLeft,ArrowRight,CalendarDays,Check,CheckCircle2,Clock3,FileCheck2,FileText,Info,LockKeyhole,MessageSquareText,Plus,Search,ShieldAlert,ShieldCheck,Sparkles,Users,X,Star,Video,Filter,ClipboardCheck,Download,RotateCcw} from 'lucide-react';
import {MentorAgreement,MentorDeliverable,MentorEvent,MentorGoal,MentorReadinessItem,MentorRoleData,MentorRoleRequest,MentorRoleSession,MentorStartup,useMentorRole} from '@/context/MentorRoleContext';
import styles from './MentorRoll.module.css';
const sections=['dashboard','requests','discover','startups','workspace','startup','sessions','session-detail','readiness','deliverables','earnings','agreements','agreement-detail','impact','events','event-detail','messages','settings'];
const titleFor=(s:string)=>({'dashboard':'Mentor Dashboard','requests':'Startup Requests','discover':'Discover Startups','startups':'My Startups','workspace':'Mentorship Workspace','startup':'Startup Overview','sessions':'Sessions','session-detail':'Session Detail','readiness':'Readiness Sign-off','deliverables':'Deliverables','earnings':'Earnings & Payouts','agreements':'Agreements','agreement-detail':'Agreement detail','impact':'Impact & Reviews','events':'Investor Events','event-detail':'Event detail','messages':'Messages','settings':'Mentor Profile & Settings'} as Record<string,string>)[s]||'Mentor Dashboard';
const rid=(p:string)=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const fmt=(s:string)=>s?new Date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not scheduled';
export default function MentorRollPage({section='dashboard',mentorshipId,sessionId,agreementId,eventId}:{section?:string;mentorshipId?:string;sessionId?:string;agreementId?:string;eventId?:string}){const [activeSection,setActiveSection]=useState(sections.includes(section)?section:'dashboard');useEffect(()=>{setActiveSection(sections.includes(section)?section:'dashboard');if(section&&section!=='dashboard'){const timer=window.setTimeout(()=>{const target=document.getElementById(section)||document.getElementById(`mentor-${section}`);target?.scrollIntoView({behavior:'smooth',block:'start'})},120);return()=>window.clearTimeout(timer)}},[section]);const {data,setData}=useMentorRole();const [toast,setToast]=useState('');const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),3000)};const selected=data.startups.find(s=>s.id===mentorshipId);return <div className={styles.rollPage}><a className={styles.skip} href="#mentor-dashboard">Skip to mentor content</a><header className={styles.pageHeader}><div><span className={styles.eyebrow}>Mentor role · core workspace</span><h1>{titleFor(activeSection)}</h1><p>One continuous workspace for requests, mentorships, sessions and impact.</p></div><span className={styles.localTag}><LockKeyhole size={13}/> Private local demo</span></header><div className={styles.verificationBanner}><ShieldAlert size={17}/><span><strong>{data.verifiedStatus==='Verified'?'Mentor profile verified':'Your mentor profile is under review'}</strong><small>{data.verifiedStatus==='Verified'?'Profile verification status is not connected to an admin service.':'You can edit your profile and capacity, but cannot accept startups, invite, schedule sessions or sign off items.'}</small></span><a href="#mentor-settings">View status <ArrowRight size={12}/></a></div><div className={styles.mobileSections}><label>Jump to section<select value={activeSection} onChange={e=>{setActiveSection(e.target.value);document.getElementById(e.target.value)?.scrollIntoView({behavior:'smooth'})}}>{sections.map(s=><option key={s} value={s}>{titleFor(s)}</option>)}</select></label></div><nav className={styles.rollToc} aria-label="Page sections">{sections.map(s=><a key={s} href={`#mentor-${s}`} className={activeSection===s?styles.tocActive:styles.toc}>{titleFor(s)}</a>)}</nav>
 <section id="mentor-dashboard" className={styles.rollSection}><SectionHeader title={`Good day, ${data.privateProfile.name}`} subtitle="Your day at a glance. No account profile or live mentor data is connected."><div className={styles.availabilityBox}><span>Availability</span><strong>{data.availability}</strong><button disabled={data.verifiedStatus!=='Verified'} onClick={()=>notify('Availability options are editable in profile settings, but not published.')}>Change status</button></div></SectionHeader><div className={styles.kpis}>{[['Active startups',`${data.startups.filter(s=>s.status==='Active').length} / ${data.capacity}`,'Local mentorship records'],['Sessions this month',data.startups.flatMap(s=>s.sessions).filter(s=>new Date(s.date).getMonth()===new Date().getMonth()).length,'Local records only'],['Sign-offs pending',data.startups.flatMap(s=>s.readinessItems).filter(i=>i.status==='Submitted for sign-off').length,'No sign-off service'],['Earnings this month','—','Billing not connected']].map(x=><div key={String(x[0])}><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</div><div className={styles.mainGrid}><main className={styles.stack}><Card title="Needs your attention" subtitle="Priority items are drawn from local records only.">{attention(data).length?attention(data).map(a=><div className={styles.attentionRow} key={a.label}><span className={styles.attentionIcon}><Activity size={14}/></span><span><strong>{a.label}</strong><small>{a.detail}</small></span><Link href={a.href}>Open <ArrowRight size={12}/></Link></div>):<Empty title="You're all caught up." detail="There are no incoming requests, sign-offs or pending deliverables in this browser." action="Discover startups" href="/mentor/discover"/>}</Card><Card title="Today's sessions" subtitle="Asia/Kolkata · video and calendar are not connected."><Empty title="No sessions today." detail="No session records are available. Session booking is disabled while verification is pending." action="Review requests" href="/mentor/requests"/></Card><Card title="My startups at a glance" subtitle="Active, paused and past mentorships.">{data.startups.length?data.startups.slice(0,6).map(s=><StartupCompact key={s.id} startup={s}/>):<Empty title="No startup mentorships yet." detail="Connected startup requests and mentorship records are unavailable." action="View requests" href="/mentor/requests"/>}<Link className={styles.textLink} href="/mentor/startups">View all startups <ArrowRight size={12}/></Link></Card><Card title="Impact trend" subtitle="Readiness history and mentor attribution are not connected."><div className={styles.chartEmpty}><Activity size={21}/><strong>No impact data available</strong><small>No readiness scores are calculated or shown for unshared startup records.</small></div></Card></main><aside className={styles.stack}><Card title="Next session"><p className={styles.emptyText}>No confirmed sessions. Calendar service is disconnected.</p><Button disabled>Join</Button></Card><Card title="Capacity"><div className={styles.capacityRow}><strong>{data.startups.filter(s=>s.status==='Active').length} of {data.capacity} slots used</strong><Link href="#mentor-settings">Edit capacity</Link></div><Progress value={data.capacity?data.startups.filter(s=>s.status==='Active').length/data.capacity*100:0}/></Card><Card title="Earnings snapshot"><div className={styles.earningsRow}><span>This month</span><strong>Not connected</strong></div><div className={styles.earningsRow}><span>Pending payout</span><strong>Not connected</strong></div><Link className={styles.textLink} href="#mentor-earnings">Earnings page <ArrowRight size={12}/></Link></Card><Card title="Tip"><p className={styles.tip}>Specific, evidence-based sign-off notes help founders understand what to improve.</p><small className={styles.caption}>General guidance · no startup-specific recommendation.</small></Card></aside></div></section>
 <RequestsSection data={data} setData={setData} notify={notify}/><DiscoverSection data={data} notify={notify}/><StartupsSection data={data}/><WorkspaceSection startup={selected} mentorshipId={mentorshipId} data={data} setData={setData} notify={notify}/><StartupOverview startup={selected} mentorshipId={mentorshipId}/><SessionsSection data={data} setData={setData} notify={notify}/><SessionDetailSection data={data} setData={setData} sessionId={sessionId} notify={notify}/><ReadinessSection startup={selected} mentorshipId={mentorshipId} data={data} setData={setData} notify={notify}/><DeliverablesSection data={data} setData={setData} notify={notify}/><EarningsSection data={data} setData={setData} notify={notify}/><AgreementsSection data={data}/><AgreementDetailSection data={data} agreementId={agreementId} notify={notify}/><ImpactSection data={data} setData={setData} notify={notify}/><EventsSection data={data} notify={notify}/><EventDetailSection data={data} eventId={eventId} notify={notify}/><MessagesSection data={data}/><SettingsSection data={data} setData={setData} notify={notify}/><p className={styles.disclaimer}><Info size={12}/> All mentor information is browser-local. Startup sharing, verification, role permissions, messaging, calendar, video, files, sign-off, billing and notifications are not connected.</p>{toast&&<div role="status" className={styles.toast}><CheckCircle2 size={15}/>{toast}<button onClick={()=>setToast('')} aria-label="Dismiss"><X size={13}/></button></div>}</div>}
function SectionHeader({title,subtitle,children}:{title:string;subtitle?:string;children?:React.ReactNode}){return <header className={styles.sectionHeader}><div><span className={styles.sectionKicker}>Mentor workspace</span><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{children}</header>}
function Card({title,subtitle,children,action}:{title:string;subtitle?:string;children:React.ReactNode;action?:React.ReactNode}){return <article className={styles.card}><div className={styles.cardHead}><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</article>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className={styles.field}><span>{label}</span>{children}</label>}
function Button({children,onClick,disabled,primary=false,title}:{children:React.ReactNode;onClick?:()=>void;disabled?:boolean;primary?:boolean;title?:string}){return <button title={title} className={primary?styles.primary:styles.secondary} disabled={disabled} onClick={onClick}>{children}</button>}
function Empty({title,detail,action,href}:{title:string;detail:string;action?:string;href?:string}){return <div className={styles.empty}><span><Users size={18}/></span><strong>{title}</strong><p>{detail}</p>{action&&href&&<Link className={styles.secondary} href={href}>{action} <ArrowRight size={12}/></Link>}</div>}
function Notice({children,warning=false}:{children:React.ReactNode;warning?:boolean}){return <div className={`${styles.notice} ${warning?styles.noticeWarning:''}`}><Info size={14}/><span>{children}</span></div>}
function Progress({value}:{value:number}){return <div className={styles.progress}><i style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div>}
function Status({value}:{value:string}){return <span className={`${styles.status} ${styles['status-'+value.toLowerCase().replace(/[^a-z]+/g,'-')]||''}`}>{value}</span>}
function attention(data:MentorRoleData){const count=data.requests.filter(r=>r.status==='Requested').length+data.startups.flatMap(s=>s.readinessItems).filter(i=>i.status==='Submitted for sign-off').length+data.startups.flatMap(s=>s.deliverables).filter(d=>d.status==='Submitted').length;return count?[{label:`${count} items require review`,detail:'Local request or submitted item',href:'/mentor/requests'}]:[]}
function StartupCompact({startup}:{startup:MentorStartup}){const signed=startup.readinessItems.filter(i=>i.status==='Signed off').length;return <Link className={styles.startupCompact} href={`/mentor/startups/${startup.id}`}><span className={styles.startupLogo}>{startup.startupName.slice(0,1)}</span><span><strong>{startup.startupName}</strong><small>{startup.stage} · {startup.sector}</small><small>{signed} of {startup.readinessItems.length} local sign-offs</small></span><Status value={startup.status}/></Link>}
function RequestsSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const [tab,setTab]=useState('Incoming');const [query,setQuery]=useState('');const [selected,setSelected]=useState<MentorRoleRequest|null>(null);const list=data.requests.filter(r=>(tab==='Incoming'?r.status==='Requested':tab==='Past'?['Declined','Expired'].includes(r.status):tab==='Invitations sent'?r.status==='Countered':false)&&`${r.startupName} ${r.goal}`.toLowerCase().includes(query.toLowerCase()));return <section id="mentor-requests" className={styles.rollSection}><SectionHeader title="Startup requests" subtitle="Review incoming mentorship requests and startup-shared information."><Link className={styles.secondary} href="#mentor-settings">Edit profile</Link><Link className={styles.primary} href="#mentor-discover">Discover startups</Link></SectionHeader><Notice warning>Profile verification is pending. Accept, decline, counter, invite and message actions are disabled. No request service is connected.</Notice><div className={styles.toolbar}><nav className={styles.tabs}>{['Incoming','Invitations sent','Auto-match suggestions','Past'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search requests"/></label></div><div className={styles.twoColumn}><main className={styles.stack}>{list.length?list.map(r=><article key={r.id} className={styles.requestCard}><div className={styles.requestHead}><span className={styles.startupLogo}>{r.startupName.slice(0,1)}</span><div><strong>{r.startupName}</strong><small>{r.oneLiner} · {r.stage} · {r.sector}</small></div><Status value={r.status}/></div><p>{r.goal}</p><div className={styles.tags}>{r.needs.map(n=><span key={n}>{n}</span>)}</div><small className={styles.caption}>Request details are local only · {r.cadence} · {r.duration}</small><div className={styles.inlineActions}><Button onClick={()=>setSelected(r)}>View details</Button><Button primary disabled>Accept · verification pending</Button><Button disabled>Decline</Button></div></article>):<Empty title={tab==='Incoming'?'No requests yet.':'No records in this tab.'} detail="Incoming startup requests, opt-in matching and invitations are not connected. No sample startup data is shown." action="Edit profile" href="#mentor-settings"/>}</main><aside className={styles.stack}><Card title="Request settings"><p className={styles.emptyText}>Capacity: {data.startups.filter(s=>s.status==='Active').length} active of {data.capacity}. Your status is {data.availability}.</p><Link className={styles.textLink} href="#mentor-settings">Review profile and capacity <ArrowRight size={12}/></Link></Card><Card title="Privacy"><p className={styles.emptyText}>Only fields a startup explicitly shares should appear here. No sharing permissions are connected.</p></Card></aside></div>{selected&&<div className={styles.backdrop}><section className={styles.modal} role="dialog" aria-modal="true" aria-labelledby="request-title"><header><div><span className={styles.sectionKicker}>Request · local record</span><h3 id="request-title">{selected.startupName}</h3></div><button className={styles.iconButton} onClick={()=>setSelected(null)} aria-label="Close"><X size={16}/></button></header><div className={styles.modalBody}><Notice warning>Startup details below are only those marked shared. This request record isn't connected to a startup account.</Notice><p><strong>Goal</strong><br/>{selected.goal}</p><p><strong>Needs</strong><br/>{selected.needs.join(', ')}</p><p><strong>Terms</strong><br/>{selected.cadence} · {selected.duration} · {selected.feeTerms} · {selected.equityTerms}</p><p><strong>Shared files</strong><br/>{selected.sharedFiles.join(', ')||'None'}</p><label className={styles.checkLabel}><input type="checkbox"/> Do you have a conflict of interest?</label><textarea placeholder="Conflict note"/><div className={styles.inlineActions}><Button disabled>Counter terms</Button><Button disabled>Ask a question</Button><Button disabled>Decline · verification pending</Button><Button primary disabled>Accept · verification pending</Button></div></div></section></div>}</section>}
function DiscoverSection({data,notify}:{data:MentorRoleData;notify:(s:string)=>void}){const [query,setQuery]=useState('');return <section id="mentor-discover" className={styles.rollSection}><SectionHeader title="Discover startups" subtitle="Only startups that opted in should appear. Directory and matching services are not connected."><Button disabled onClick={()=>notify('Invite flow is disabled until mentor verification is complete.')}>Invite startup</Button></SectionHeader><div className={styles.twoColumn}><aside className={styles.card}><h3>Filters</h3>{[['Stage','All stages'],['Industry','All sectors'],['Need','Any need'],['Location','Any region'],['Team size','Any team']].map(([l,v])=><label className={styles.field} key={l}>{l}<select><option>{v}</option>{l==='Stage'&&['Idea','Prototype','Early revenue','Mature'].map(x=><option key={x}>{x}</option>)}</select></label>)}<label className={styles.checkLabel}><input type="checkbox" checked disabled readOnly/> Verified startups only</label><label className={styles.checkLabel}><input type="checkbox"/> Needs a mentor</label></aside><main className={styles.stack}><div className={styles.discoverToolbar}><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search opted-in startups"/></label><select><option>Best fit</option><option>Newest</option><option>Highest readiness</option><option>Most in need</option></select></div><Notice warning>Discovery is locked while verification is pending. No startup profiles, readiness scores or traction metrics are fabricated for this page.</Notice><Empty title="No opted-in startups available." detail="Startup opt-in, verification, auto-match and profile-sharing services are not connected. Results are intentionally empty."/><small className={styles.caption}>Search: {query||'All startups'} · {data.savedStartupIds.length} private saved identifiers</small></main></div></section>}
function StartupsSection({data}:{data:MentorRoleData}){const [tab,setTab]=useState('Active');const [view,setView]=useState('Cards');const [query,setQuery]=useState('');const list=data.startups.filter(s=>s.status===tab&&s.startupName.toLowerCase().includes(query.toLowerCase()));return <section id="mentor-startups" className={styles.rollSection}><SectionHeader title="My startups" subtitle="Active, paused and past mentorships. Records are limited to your local workspace."><Link className={styles.secondary} href="#mentor-requests">View requests</Link><Link className={styles.secondary} href="#mentor-discover">Discover startups</Link></SectionHeader><div className={styles.stats}>{[['Active',data.startups.filter(s=>s.status==='Active').length],['Capacity',`${data.startups.filter(s=>s.status==='Active').length} of ${data.capacity}`],['Sessions this month',data.startups.flatMap(s=>s.sessions).length],['Sign-offs pending',data.startups.flatMap(s=>s.readinessItems).filter(i=>i.status==='Submitted for sign-off').length]].map(x=><div key={String(x[0])}><span>{x[0]}</span><strong>{x[1]}</strong></div>)}</div><div className={styles.toolbar}><nav className={styles.tabs}>{['Active','Paused','Completed'].map(t=><button className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)} key={t}>{t}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search startups"/></label><div className={styles.viewToggle}><button className={view==='Cards'?styles.tabActive:styles.tab} onClick={()=>setView('Cards')}>Cards</button><button className={view==='Table'?styles.tabActive:styles.tab} onClick={()=>setView('Table')}>Table</button></div></div><div id="mentor-main" className={styles.stack}>{list.length?(view==='Cards'?list.map(s=><StartupCard key={s.id} startup={s}/>):<div className={styles.tableWrap}><table><thead><tr>{['Startup','Stage','Status','Started','Sessions','Sign-off progress','Open deliverables','Actions'].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{list.map(s=><tr key={s.id}><td>{s.startupName}</td><td>{s.stage}</td><td>{s.status}</td><td>{fmt(s.startedAt)}</td><td>{s.sessions.length}</td><td>{s.readinessItems.filter(i=>i.status==='Signed off').length}/{s.readinessItems.length}</td><td>{s.deliverables.filter(d=>!['Accepted'].includes(d.status)).length}</td><td><Link href={`/mentor/startups/${s.id}`}>Open</Link></td></tr>)}</tbody></table></div>):<Empty title="You aren't mentoring any startups yet." detail="No accepted mentorships are connected to this mentor account." action="View requests" href="#mentor-requests"/>}</div></section>}
function StartupCard({startup}:{startup:MentorStartup}){const signed=startup.readinessItems.filter(i=>i.status==='Signed off').length;return <article className={styles.startupCard}><span className={styles.startupLogo}>{startup.startupName.slice(0,1)}</span><div className={styles.startupCardBody}><div className={styles.cardLine}><strong>{startup.startupName}</strong><Status value={startup.status}/><span className={styles.stagePill}>Stage: {startup.stage}</span></div><p>{startup.sector} · Startup details shared only when enabled.</p><div className={styles.signoffLabel}><span>{signed} of {startup.readinessItems.length} local sign-offs</span><Progress value={startup.readinessItems.length?signed/startup.readinessItems.length*100:0}/></div><small>Started {fmt(startup.startedAt)} · {startup.sessions.length} locally logged sessions</small><div className={styles.inlineActions}><Link className={styles.primary} href={`/mentor/startups/${startup.id}`}>Open workspace</Link><Link className={styles.secondary} href={`/mentor/startups/${startup.id}/startup`}>View shared overview</Link><Button disabled>Message</Button><Button disabled>Book session</Button></div></div></article>}
function WorkspaceSection({startup,mentorshipId,data,setData,notify}:{startup?:MentorStartup;mentorshipId?:string;data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const [tab,setTab]=useState('Overview');const [goal,setGoal]=useState('');const [sharedNote,setSharedNote]=useState('');const [privateNote,setPrivateNote]=useState('');if(mentorshipId&&!startup)return <section id="mentor-workspace" className={styles.rollSection}><SectionHeader title="Mentorship workspace" subtitle="This record isn't accessible from the current mentor workspace."/><Notice warning>Per-startup access is required. Unknown mentorship identifiers return no startup data.</Notice><Empty title="Mentorship not found." detail="No active, paused or past mentorship is attached to this local account." action="View my startups" href="/mentor/startups"/></section>;return <section id="mentor-workspace" className={styles.rollSection}><SectionHeader title={startup?`Workspace · ${startup.startupName}`:'Mentorship workspace'} subtitle={startup?`${startup.status} · Started ${fmt(startup.startedAt)} · ${startup.cadence}`:'Structured space for one accepted mentorship.'}>{startup&&<><Link className={styles.secondary} href={`/mentor/startups/${startup.id}/startup`}>View startup</Link><Button disabled>Message</Button><Button disabled>Book session</Button></>}</SectionHeader>{startup?<><Notice warning>Startup sharing and service permissions are not connected. Treat every shared field below as unavailable unless a real grant is shown.</Notice><div className={styles.workspaceTop}><span className={styles.startupLogo}>{startup.startupName.slice(0,1)}</span><div><strong>{startup.startupName}</strong><small>{startup.stage} · {startup.sector} · {startup.status}</small></div><span className={styles.status}>{startup.status}</span></div><nav className={styles.tabs}>{['Overview','Plan','Sessions','Deliverables','Readiness','Notes','Files','Messages'].map(t=><button key={t} onClick={()=>setTab(t)} className={tab===t?styles.tabActive:styles.tab}>{t}</button>)}</nav><div className={styles.twoColumn}><main className={styles.stack}>{tab==='Overview'?<><Card title="Mentorship overview"><div className={styles.stats}><div><span>Goals complete</span><strong>{startup.goals.filter(g=>g.status==='Done').length}/{startup.goals.length}</strong></div><div><span>Sessions</span><strong>{startup.sessions.length}</strong></div><div><span>Open deliverables</span><strong>{startup.deliverables.filter(d=>d.status!=='Accepted').length}</strong></div></div><h4>Next steps</h4><p>{startup.sessions.find(s=>s.status==='Scheduled'||s.status==='Confirmed')?.topic||'No upcoming session'}</p><p>{startup.deliverables.filter(d=>d.status==='Submitted').length} deliverables waiting · {startup.readinessItems.filter(i=>i.status==='Submitted for sign-off').length} sign-offs submitted</p></Card><Card title="Items shared by the startup"><SharedList startup={startup}/></Card></>:tab==='Plan'?<Card title="Goals and cadence" subtitle="Goal edits are local proposals; acceptance/history service is disconnected."><p>{startup.cadence} · {startup.status}</p><form className={styles.inlineForm} onSubmit={e=>{e.preventDefault();if(!goal.trim())return;const item:MentorGoal={id:rid('goal'),title:goal.trim(),description:'',targetDate:'',successMeasure:'',owner:'Mentor',status:'Proposed'};setData(d=>({...d,startups:d.startups.map(s=>s.id===startup.id?{...s,goals:[...s.goals,item]}:s)}));setGoal('');notify('Goal proposal saved locally; startup was not notified.')}}><input value={goal} onChange={e=>setGoal(e.target.value)} placeholder="Propose a goal"/><Button primary disabled={!goal.trim()||data.verifiedStatus!=='Verified'}><Plus size={12}/> Add proposed goal</Button></form>{startup.goals.map(g=><GoalRow key={g.id} goal={g}/>)}</Card>:tab==='Sessions'?<Card title="Sessions">{startup.sessions.length?startup.sessions.map(s=><div className={styles.sessionRow} key={s.id}><CalendarDays size={13}/><span><strong>{s.topic}</strong><small>{fmt(s.date)} · {s.duration} min · {s.timezone||'Asia/Kolkata'}</small></span><Link className={styles.textLink} href={`/mentor/sessions/${s.id}`}>Open <ArrowRight size={11}/></Link></div>):<Empty title="No sessions recorded." detail="Session booking and video services are not connected."/>}<Link className={styles.textLink} href="/mentor/sessions">All sessions <ArrowRight size={11}/></Link></Card>:tab==='Deliverables'?<Card title="Deliverables">{startup.deliverables.length?startup.deliverables.map(d=><div className={styles.deliverableRow} key={d.id}><span><strong>{d.title}</strong><small>Due {fmt(d.dueDate)} · {d.owner}</small></span><Status value={d.status}/></div>):<Empty title="No deliverables." detail="No startup task records are shared with this mentor."/>}<Link className={styles.textLink} href="/mentor/deliverables">Review queue <ArrowRight size={11}/></Link></Card>:tab==='Readiness'?<Card title="Readiness sign-off">{startup.readinessItems.length?startup.readinessItems.map(i=><div className={styles.deliverableRow} key={i.id||i.title}><span><strong>{i.title}</strong><small>{i.shared?'Shared evidence':'Not shared'}</small></span><Status value={i.status}/></div>):<Empty title="No readiness items shared." detail="Readiness evidence and sign-off permissions are unavailable until shared."/>}<Link className={styles.textLink} href={`/mentor/startups/${startup.id}/readiness`}>Open sign-off page <ArrowRight size={11}/></Link></Card>:tab==='Notes'?<Card title="Notes"><label className={styles.field}>Shared note<textarea value={sharedNote} onChange={e=>setSharedNote(e.target.value)} placeholder="Share a note only after a real mentorship is connected."/></label><Button disabled={data.verifiedStatus!=='Verified'} onClick={()=>notify('Note saved locally only; startup was not notified.')}>Save shared note</Button><label className={styles.field}><span><LockKeyhole size={13}/> Private notes · only visible to you</span><textarea value={privateNote} onChange={e=>setPrivateNote(e.target.value)} maxLength={10000} placeholder="Private notes stay out of startup-facing views."/></label><small className={styles.caption}>{privateNote.length}/10,000 · Local browser storage only.</small></Card>:tab==='Files'?<Card title="Files"><Empty title="No files shared." detail="The startup has not granted document access. No files are displayed or fetched."/></Card>:<Card title="Messages"><Empty title="Secure messages are not connected." detail="No message has been sent. Private notes are not shown to the startup."/></Card>}</main><aside className={styles.stack}><Card title="Startup snapshot"><SharedList startup={startup}/><p className={styles.emptyText}>Readiness score, traction and team details: Not shared.</p></Card><Card title="Terms"><p className={styles.emptyText}>Fee model and agreement are not connected.</p></Card></aside></div></>:<><Card title="Workspace preview"><Empty title="No mentorship selected." detail="Open a startup workspace from My Startups. Unknown or unassigned records stay inaccessible." action="Go to My Startups" href="#mentor-startups"/></Card></>}</section>}
function GoalRow({goal}:{goal:MentorGoal}){return <div className={styles.goalRow}><span><strong>{goal.title}</strong><small>{goal.description||'Description not set'} · Owner: {goal.owner} · Target: {goal.targetDate||'Not set'} · Success measure: {goal.successMeasure||'Not set'}</small></span><span className={styles.status}>{goal.status}</span></div>}
function SharedList({startup}:{startup:MentorStartup}){return <div className={styles.sharedList}>{['Profile','Traction','Team','Documents','Funding','Readiness'].map(k=><div key={k}><span><LockKeyhole size={12}/>{k}</span><strong>{startup.sharedCategories.includes(k)?'Shared':'Not shared'}</strong></div>)}</div>}
function StartupOverview({startup,mentorshipId}:{startup?:MentorStartup;mentorshipId?:string}){if(!mentorshipId)return <section id="mentor-startup" className={styles.rollSection}><SectionHeader title="Startup overview · read only" subtitle="This section opens only through a mentorship workspace."/><Empty title="Choose an assigned startup." detail="No startup details are fetched unless the startup has shared them through an active mentorship." action="My startups" href="#mentor-startups"/></section>;if(!startup)return <section id="mentor-startup" className={styles.rollSection}><SectionHeader title="Startup overview unavailable" subtitle="Read-only identity and shared data."/><Notice warning>This mentorship ID is not assigned to this mentor. No startup information was rendered.</Notice><Empty title="Access denied / not found." detail="Only startups assigned to this mentor are available." action="My startups" href="/mentor/startups"/></section>;return <section id="mentor-startup" className={styles.rollSection}><SectionHeader title={`${startup.startupName} · shared overview`} subtitle="Read-only view. Showing only fields the startup has chosen to share."><Link className={styles.secondary} href={`/mentor/startups/${startup.id}`}>Open workspace</Link></SectionHeader><Notice>Read-only view. Shared categories are listed; unshared fields remain hidden.</Notice><div className={styles.twoColumn}><main className={styles.stack}><Card title="Startup identity"><h3>{startup.startupName}</h3><p>{startup.stage} · {startup.sector}</p><SharedList startup={startup}/></Card><Card title="About and pitch summary"><NotShared category="Profile" shared={startup.sharedCategories.includes('Profile')}/></Card><Card title="Traction highlights"><NotShared category="Traction metrics" shared={startup.sharedCategories.includes('Traction')}/></Card><Card title="Team"><NotShared category="Team and contact details" shared={startup.sharedCategories.includes('Team')}/></Card><Card title="Documents shared with you"><NotShared category="Documents" shared={startup.sharedCategories.includes('Documents')}/></Card><Card title="Funding and use of funds"><NotShared category="Funding information" shared={startup.sharedCategories.includes('Funding')}/></Card></main><aside className={styles.stack}><Card title="Your mentorship"><Status value={startup.status}/><p>{startup.sessions.length} sessions · {startup.cadence}</p><Link className={styles.textLink} href={`/mentor/startups/${startup.id}`}>Open workspace</Link></Card><Card title="Readiness"><p className={styles.emptyText}>Score and evidence are not shared.</p><Progress value={startup.readinessItems.length?startup.readinessItems.filter(i=>i.status==='Signed off').length/startup.readinessItems.length*100:0}/></Card></aside></div></section>}
function NotShared({category,shared}:{category:string;shared:boolean}){return <div className={styles.sharedNotice}>{shared?<><LockKeyhole size={14}/><span>{category} shared; details are not included in this local prototype.</span></>:<><LockKeyhole size={14}/><span>{category}: Not shared. Ask the startup to share this information through the connected workspace.</span></>}</div>}
function SessionsSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){
 const [tab,setTab]=useState('Upcoming');const [query,setQuery]=useState('');const [week,setWeek]=useState(0);const verified=data.verifiedStatus==='Verified';
 const sessions=data.startups.flatMap(startup=>startup.sessions.map(session=>({...session,startupName:startup.startupName,startupId:startup.id})));
 const upcoming=sessions.filter(s=>['Scheduled','Confirmed','Reschedule requested'].includes(s.status)&&new Date(s.date)>=new Date()).sort((a,b)=>a.date.localeCompare(b.date));
 const needs=sessions.filter(s=>s.status==='Completed'&&!s.notes?.trim()).sort((a,b)=>a.date.localeCompare(b.date));
 const past=sessions.filter(s=>s.status==='Completed'||s.status==='Cancelled').sort((a,b)=>b.date.localeCompare(a.date));
 const list=(tab==='Upcoming'?upcoming:tab==='Needs summary'?needs:past).filter(s=>`${s.startupName} ${s.topic}`.toLowerCase().includes(query.toLowerCase()));
 const now=new Date();const monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7)+week*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);return d});
 const updateStatus=(sessionId:string,status:MentorRoleSession['status'])=>{setData(d=>({...d,startups:d.startups.map(st=>({...st,sessions:st.sessions.map(s=>s.id===sessionId?{...s,status}:s)}))}));notify(`Session marked ${status} in the local record. No one was notified.`)};
 const exportCsv=()=>{const rows=[['Date','Startup','Topic','Duration','Type','Status','Summary'],...past.map(s=>[s.date,s.startupName,s.topic,s.duration,s.type||'Regular',s.status,s.notes?'Added':'Missing'])];const blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mentor-sessions-local.csv';a.click();URL.revokeObjectURL(url)};
 return <section id="mentor-sessions" className={styles.rollSection}><SectionHeader title="Sessions" subtitle="One list across your mentorships. Time zone is Asia/Kolkata; calendar and video services are disconnected."><Button disabled={!verified||!data.startups.some(s=>s.status==='Active')}>+ Schedule session</Button></SectionHeader><div className={styles.stats}>{[['Sessions this week',upcoming.filter(s=>{const d=new Date(s.date);return d>=monday&&d<new Date(monday.getTime()+7*86400000)}).length],['Hours mentored this month',Math.round(sessions.filter(s=>new Date(s.date).getMonth()===now.getMonth()).reduce((n,s)=>n+s.duration,0)/60*10)/10],['Needs summary',needs.length],['Reschedule requests',sessions.filter(s=>s.status==='Reschedule requested').length]].map(x=><div key={String(x[0])}><span>{x[0]}</span><strong>{x[1]}</strong></div>)}</div><Notice warning>{verified?'Calendar and managed video are not connected.':'Your mentor profile is under review. Session booking, joining and changes are disabled.'}</Notice><div className={styles.toolbar}><nav className={styles.tabs}>{['Upcoming','Needs summary','Past','Calendar'].map(t=><button className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)} key={t}>{t}{t==='Needs summary'&&needs.length>0?` · ${needs.length}`:''}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search startup or topic"/></label><Button onClick={exportCsv} disabled={tab!=='Past'}><Download size={12}/> Export CSV</Button></div><div className={styles.twoColumn}><main className={styles.stack}>{tab==='Calendar'?<div className={styles.card}><div className={styles.cardHead}><div><h3>Week calendar</h3><p>Sessions remain available as a list below.</p></div><div className={styles.inlineActions}><Button onClick={()=>setWeek(w=>w-1)}>Previous</Button><Button onClick={()=>setWeek(0)}>Today</Button><Button onClick={()=>setWeek(w=>w+1)}>Next</Button></div></div><div className={styles.weekCalendar}>{days.map(day=><div key={day.toISOString()}><strong>{day.toLocaleDateString('en-IN',{weekday:'short'})}</strong><small>{day.toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</small>{sessions.filter(s=>new Date(s.date).toDateString()===day.toDateString()).map(s=><Link href={`/mentor/sessions/${s.id}`} key={s.id}>{new Date(s.date).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})} · {s.topic}</Link>)}</div>)}</div><small className={styles.caption}>Availability blocks and conflicts are not synced.</small></div>:list.length?list.map(s=><MentorSessionCard key={s.id} session={s} verified={verified} action={tab==='Needs summary'?'Add summary':'Open'} onStatus={updateStatus}/>):<Empty title={tab==='Needs summary'?'No session summaries are waiting.':tab==='Past'?'No past sessions.':'No sessions scheduled.'} detail={tab==='Upcoming'?'Book from an active startup workspace after verification; calendar invitations are unavailable.':tab==='Needs summary'?'Completed sessions without a summary would appear here.':'No session records are available in this browser.'} action="Open My Startups" href="#mentor-startups"/>}</main><aside className={styles.stack}><Card title="Today" subtitle="Asia/Kolkata">{sessions.filter(s=>new Date(s.date).toDateString()===now.toDateString()).length?sessions.filter(s=>new Date(s.date).toDateString()===now.toDateString()).map(s=><MentorSessionCard key={s.id} session={s} verified={verified} action="Prepare" onStatus={updateStatus}/>):<p className={styles.emptyText}>No sessions today.</p>}</Card><Card title="Availability this week"><p className={styles.emptyText}>Open slots: not connected</p><Link className={styles.textLink} href="#mentor-settings">Edit availability <ArrowRight size={12}/></Link></Card><Card title="Hours vs capacity"><p className={styles.emptyText}>Capacity: not connected to session billing or availability.</p></Card></aside></div></section>
}
function MentorSessionCard({session,verified,action,onStatus}:{session:MentorRoleSession&{startupName:string;startupId:string};verified:boolean;action:string;onStatus:(id:string,status:MentorRoleSession['status'])=>void}){const diff=new Date(session.date).getTime()-Date.now();const withinTen=diff>=0&&diff<=10*60000;const soon=diff>0&&diff<30*60000;return <article className={`${styles.sessionCard} ${soon?styles.sessionSoon:''}`}><span className={styles.sessionDate}><CalendarDays size={14}/><strong>{new Date(session.date).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})}</strong><small>{new Date(session.date).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})} {session.timezone||'IST'}</small></span><div className={styles.sessionInfo}><strong>{session.startupName} · {session.topic}</strong><small>{session.duration} min · {session.type||'Regular'} · {session.attendees?.join(', ')||'No attendee list'}</small><Status value={session.status}/></div><div className={styles.inlineActions}><Link className={styles.secondary} href={`/mentor/sessions/${session.id}`}>{action}</Link><Button disabled={!verified||!withinTen} title={!verified?'Verification required':'Join opens 10 minutes before start'}><Video size={12}/> Join</Button><Button disabled={!verified||!['Scheduled','Confirmed'].includes(session.status)} onClick={()=>onStatus(session.id,'Reschedule requested')}>Reschedule</Button></div></article>}
function SessionDetailSection({data,setData,sessionId,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;sessionId?:string;notify:(s:string)=>void}){
 const found=sessionId?data.startups.flatMap(startup=>startup.sessions.map(session=>({...session,startupName:startup.startupName,startupId:startup.id,statusMentorship:startup.status}))).find(s=>s.id===sessionId):undefined;
 const [tab,setTab]=useState('Agenda');const [summary,setSummary]=useState(found?.notes||'');const [decisions,setDecisions]=useState(found?.decisions||'');const [privateNotes,setPrivateNotes]=useState(found?.privateNotes||'');const [progress,setProgress]=useState(found?.progress||'On track');const verified=data.verifiedStatus==='Verified';
 const update=(patch:Partial<MentorRoleSession>)=>found&&setData(d=>({...d,startups:d.startups.map(st=>st.id===found.startupId?{...st,sessions:st.sessions.map(s=>s.id===found.id?{...s,...patch}:s)}:st)}));
 const saveSummary=(e:FormEvent)=>{e.preventDefault();if(summary.trim().length<20){notify('Summary must be at least 20 characters.');return}update({notes:summary,decisions,privateNotes,progress,status:'Completed',sharedSummary:true});notify('Summary saved in the local record; startup was not notified.')};
 if(!sessionId)return <section id="mentor-session-detail" className={styles.rollSection}><SectionHeader title="Session detail" subtitle="Open a session from the Sessions list to review its agenda, notes and summary."/><Empty title="No session selected." detail="Session records are not connected to this mentor account." action="View sessions" href="#mentor-sessions"/></section>;
 if(!found)return <section id="mentor-session-detail" className={styles.rollSection}><SectionHeader title="Session not found" subtitle="Session details are limited to assigned mentorship records."/><Notice warning>No session data was loaded for this ID. The route does not expose unassigned startup data.</Notice><Empty title="This session is unavailable." detail="It may not belong to this mentor or isn't present in the local workspace." action="Sessions" href="/mentor/sessions"/></section>;
 const tabs=['Agenda','Notes','Files','Recording','Summary and feedback'];const live=found.status==='Confirmed'&&new Date(found.date).getTime()<=Date.now()&&new Date(found.date).getTime()+found.duration*60000>Date.now();return <section id="mentor-session-detail" className={styles.rollSection}><SectionHeader title={found.topic} subtitle={`${found.startupName} · ${new Date(found.date).toLocaleString('en-IN',{weekday:'long',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})} · ${found.timezone||'Asia/Kolkata'} · ${found.duration} minutes`}><Link className={styles.secondary} href={`/mentor/startups/${found.startupId}`}>Open workspace</Link><Button disabled={!verified||!(Date.now()>=new Date(found.date).getTime()-10*60000&&Date.now()<=new Date(found.date).getTime()+found.duration*60000)}><Video size={13}/>{live?'Return to session':'Join session'}</Button></SectionHeader><Notice warning>{verified?'Managed video, calendar and recording are not connected.':'Verification pending: joining, session changes and summary submission are disabled.'}</Notice><div className={styles.workspaceTop}><span className={styles.startupLogo}>{found.startupName.slice(0,1)}</span><div><strong>{found.startupName}</strong><small>{found.type||'Regular'} · {found.attendees?.join(', ')||'Attendees not shared'}</small></div><Status value={found.status}/></div><nav className={styles.tabs}>{tabs.map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav><div className={styles.twoColumn}><main className={styles.stack}>{tab==='Agenda'?<><Card title="Shared agenda" subtitle="Editable only when the session service is connected.">{found.agendaItems?.length?found.agendaItems.map(a=><label className={styles.agendaItem} key={a.id}><input type="checkbox" checked={a.covered} disabled={!verified} onChange={e=>update({agendaItems:found.agendaItems?.map(x=>x.id===a.id?{...x,covered:e.target.checked}:x)})}/>{a.title}</label>):<Empty title="No agenda items." detail="No shared agenda has been provided."/>}</Card><Card title="Prep for you"><p className={styles.emptyText}>Last summary, open deliverables, sign-offs and shared files are not shared in this local record.</p><SharedData/></Card></>:tab==='Notes'?<Card title="Session notes"><label className={styles.field}>Shared notes<textarea value={summary} onChange={e=>setSummary(e.target.value)} maxLength={1000} placeholder="Collaborative notes (local only)"/></label><label className={styles.field}><span><LockKeyhole size={12}/> Private notes · never visible to startup</span><textarea value={privateNotes} onChange={e=>setPrivateNotes(e.target.value)} maxLength={10000}/></label><div className={styles.inlineActions}><Button disabled={!verified} onClick={()=>{update({notes:summary,privateNotes});notify('Notes saved locally; no startup notification.')}}>Save notes</Button><Button disabled>Create task</Button><Button disabled>Create deliverable</Button></div></Card>:tab==='Files'?<Card title="Session files"><Empty title="No files attached." detail="Only files explicitly shared by the startup should appear. Document access is not connected." action="Request a document"/></Card>:tab==='Recording'?<Card title="Recording"><div className={styles.sharedNotice}><LockKeyhole size={14}/><span>{found.recordingConsented?'Consent is recorded locally; no recording provider is connected.':'Recording was off. Both sides must consent before recording.'}</span></div></Card>:<><Card title="Mentor summary" subtitle="What we covered is required (20–1,000 characters). Save is local only."><form className={styles.stack} onSubmit={saveSummary}><label className={styles.field}>What we covered<textarea required minLength={20} maxLength={1000} rows={5} value={summary} onChange={e=>setSummary(e.target.value)} placeholder="Summarize the session and what you reviewed…"/></label><label className={styles.field}>Key decisions or advice<textarea value={decisions} onChange={e=>setDecisions(e.target.value)}/></label><label className={styles.field}>Progress since last session<select value={progress} onChange={e=>setProgress(e.target.value as typeof progress)}><option>On track</option><option>Behind</option><option>Ahead</option></select></label><label className={styles.checkLabel}><input type="checkbox" defaultChecked/> Share summary with startup</label><Button primary disabled={!verified||summary.trim().length<20}>Submit summary</Button></form><small className={styles.caption}>Submission would mark the session completed and notify the startup; those services aren't connected.</small></Card><Card title="Startup feedback"><p className={styles.emptyText}>{found.feedbackReceived||'Feedback is not yet shared.'}</p>{found.ratingReceived&&<p>Startup rating: {found.ratingReceived} / 5</p>}</Card></>}</main><aside className={styles.stack}><Card title="Session info"><div className={styles.sharedList}><div><span>Type</span><strong>{found.type||'Regular'}</strong></div><div><span>Timezone</span><strong>{found.timezone||'Asia/Kolkata'}</strong></div><div><span>Payment</span><strong>Not connected</strong></div></div></Card><Card title="Startup snapshot"><p className={styles.emptyText}>Stage, score, traction and sign-off progress are not shared in this record.</p></Card><Card title="Readiness items discussed"><Empty title="No items selected." detail="Readiness evidence is unavailable." action="Open sign-off" href={`/mentor/startups/${found.startupId}/readiness`}/></Card><Card title="Next session"><Button disabled={!verified}>Book follow-up</Button></Card></aside></div></section>
}
function SharedData(){return <div className={styles.sharedNotice}><LockKeyhole size={13}/><span>Shared by startup · no files or startup-only data are included.</span></div>}
function ReadinessSection({startup,mentorshipId,data,setData,notify}:{startup?:MentorStartup;mentorshipId?:string;data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){
 const [selected,setSelected]=useState<number|null>(null);const [tab,setTab]=useState('Awaiting you');const [note,setNote]=useState('');const [changeNote,setChangeNote]=useState('');const [conflict,setConflict]=useState(false);const [conflictNote,setConflictNote]=useState('');const [checks,setChecks]=useState<boolean[]>([]);const [due,setDue]=useState('');const verified=data.verifiedStatus==='Verified';const items=startup?.readinessItems||[];const signed=items.filter(i=>i.status==='Signed off').length;const pending=items.filter(i=>i.status==='Submitted');const filtered=tab==='Awaiting you'?pending:items;const updateItem=(index:number,patch:Partial<MentorStartup['readinessItems'][number]>)=>{if(!startup)return;setData(d=>({...d,startups:d.startups.map(s=>s.id===startup.id?{...s,readinessItems:s.readinessItems.map((x,i)=>i===index?{...x,...patch,updatedAt:new Date().toISOString()}:x)}:s)}))};const open=(i:number)=>{setSelected(i);const crit=items[i]?.criteria||[];setChecks(crit.map(()=>false));setNote('');setChangeNote('');setConflict(false);setConflictNote('')};const sign=()=>{if(selected===null)return;const item=items[selected];if(!note.trim()||note.trim().length<20||note.trim().length>500){notify('Sign-off note must be 20–500 characters.');return}if(!checks.length||checks.some(x=>!x)){notify('Review and check every published criterion before signing off.');return}if(!(item.evidence||[]).length){notify('A linked evidence item is required before sign-off.');return}if(conflict&&!conflictNote.trim()){notify('Add a conflict note; the item would route to admin review.');return}updateItem(selected,{status:conflict?'Pending admin review':'Signed off',note,updatedAt:new Date().toISOString()});setSelected(null);notify('Decision saved locally. No badge or startup notification was issued.')};const requestChanges=()=>{if(selected===null)return;if(changeNote.trim().length<20){notify('Change-request note must be at least 20 characters.');return}updateItem(selected,{status:'Changes requested',note:changeNote,updatedAt:new Date().toISOString()});setSelected(null);notify('Changes requested in the local record; startup was not notified.')};
 if(!mentorshipId)return <section id="mentor-readiness" className={styles.rollSection}><SectionHeader title="Readiness sign-off" subtitle="Review evidence item by item for one assigned startup."/><Empty title="Choose an assigned startup." detail="Readiness records are scoped to an active, paused or past mentorship." action="My startups" href="#mentor-startups"/></section>;
 if(!startup)return <section id="mentor-readiness" className={styles.rollSection}><SectionHeader title="Readiness sign-off unavailable"/><Notice warning>No readiness data was fetched for this mentorship ID.</Notice><Empty title="Mentorship not found." detail="The mentor does not have access to this startup record." action="My startups" href="/mentor/startups"/></section>;
 return <section id="mentor-readiness" className={styles.rollSection}><SectionHeader title={`${startup.startupName} · Readiness sign-off`} subtitle={`${startup.stage} · Shared evidence only`}><Link className={styles.secondary} href={`/mentor/startups/${startup.id}`}>Workspace</Link><Link className={styles.secondary} href={`/mentor/startups/${startup.id}/startup`}>View startup</Link></SectionHeader><Notice warning>{verified?'Sign-off decisions are saved locally only; audit and badge services are not connected.':'Your mentor profile is under review. Sign-off is disabled.'}</Notice><div className={styles.readinessHero}><div><span className={styles.sectionKicker}>Mentor sign-offs</span><h3>{signed} of {items.length} items signed off</h3><p>Badge status: {items.length&&signed===items.length?'All local items marked · badge service not connected':'Not yet · no badge will be issued here'}</p></div><div className={styles.readinessGauge}><span>—</span><small>Score not connected</small></div><Progress value={items.length?signed/items.length*100:0}/><small className={styles.caption}>No numeric readiness score is fabricated. A sign-off requires shared evidence and a written note.</small></div><div className={styles.twoColumn}><main className={styles.stack}><nav className={styles.tabs}>{['Awaiting you','All items'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav>{filtered.length?filtered.map(item=>{const ix=items.indexOf(item);return <article className={styles.readinessCard} key={item.id||item.title}><div className={styles.cardHead}><div><h3>{item.title}</h3><p>{item.criteria?.join(' · ')||'Published sign-off criteria are not available.'}</p></div><Status value={item.status}/></div><div className={styles.sharedNotice}><LockKeyhole size={13}/><span>{item.shared?'Shared by '+startup.startupName:'Not shared'}</span></div><p className={styles.emptyText}>Assigned mentor: {item.assignedMentor||'Not assigned'} · Updated {fmt(item.updatedAt||'')}</p><div className={styles.evidenceChips}>{item.evidence?.length?item.evidence.map((e,i)=><span key={i}><FileText size={12}/>{e}</span>):<small>No evidence linked. Sign-off stays unavailable.</small>}</div><div className={styles.inlineActions}><Button onClick={()=>open(ix)}>Review evidence</Button><Button primary disabled={!verified||item.status!=='Submitted'||item.assignedMentor!==data.privateProfile.name} onClick={()=>open(ix)}>Sign off</Button><Button disabled={!verified||item.status!=='Submitted'||item.assignedMentor!==data.privateProfile.name} onClick={()=>open(ix)}>Request changes</Button></div></article>}):<Empty title="Nothing is waiting for you." detail={`${startup.startupName} hasn't submitted readiness items for review.`} action="Message startup" href={`/mentor/startups/${startup.id}`}/>}</main><aside className={styles.stack}><Card title="Score breakdown"><p className={styles.emptyText}>Checklist completion: not connected</p><Progress value={0}/><p className={styles.emptyText}>Traction data: not shared</p><Progress value={0}/><p className={styles.emptyText}>Mentor feedback: not connected</p><Progress value={0}/></Card><Card title="Other mentors"><p className={styles.emptyText}>Mentor roster and item ownership are not shared.</p></Card><Card title="Timeline"><p className={styles.emptyText}>No decision history is connected.</p></Card><Card title="Guidance"><p className={styles.emptyText}>Sign off only evidence you reviewed. Never exchange a sign-off for payment, equity or other benefit.</p><Button onClick={()=>notify('Admin concern/report service is not connected.')}>Report a concern</Button></Card></aside></div>{selected!==null&&<div className={styles.modal}><section role="dialog" aria-modal="true" aria-labelledby="review-title"><header><div><span className={styles.sectionKicker}>Evidence review</span><h3 id="review-title">{items[selected].title}</h3></div><button className={styles.iconButton} onClick={()=>setSelected(null)} aria-label="Close"><X size={16}/></button></header><div className={styles.modalBody}><h4>What done means</h4>{(items[selected].criteria||[]).map((c,i)=><label className={styles.checkLabel} key={i}><input type="checkbox" checked={!!checks[i]} onChange={e=>setChecks(v=>v.map((x,j)=>j===i?e.target.checked:x))}/>{c}</label>)}{!(items[selected].criteria||[]).length&&<Notice warning>Criteria not shared; review cannot be completed.</Notice>}<h4>Evidence · view only</h4>{items[selected].evidence?.length?items[selected].evidence.map((e,i)=><div className={styles.evidenceRow} key={i}><FileText size={13}/>{e}<span>Shared by {startup.startupName}</span></div>):<Notice warning>No evidence attached. Sign-off is blocked.</Notice>}<Field label="Sign-off note · 20–500 characters"><textarea maxLength={500} value={note} onChange={e=>setNote(e.target.value)} placeholder="What you reviewed and why it passes"/></Field><Field label="Changes requested · 20–1,000 characters"><textarea maxLength={1000} value={changeNote} onChange={e=>setChangeNote(e.target.value)} placeholder="What is missing and suggested next steps"/></Field><Field label="Suggested due date"><input type="date" value={due} onChange={e=>setDue(e.target.value)}/></Field><label className={styles.checkLabel}><input type="checkbox" checked={!conflict} onChange={e=>setConflict(!e.target.checked)}/> I have no conflict of interest on this item</label>{conflict&&<Field label="Conflict note"><textarea value={conflictNote} onChange={e=>setConflictNote(e.target.value)}/></Field>}<Notice warning>You confirm you reviewed the evidence. In production, sign-offs are named, dated and visible to investors.</Notice><div className={styles.inlineActions}><Button onClick={()=>setSelected(null)}>Cancel</Button><Button disabled>Not applicable · admin review required</Button><Button disabled={!verified||changeNote.trim().length<20} onClick={requestChanges}>Request changes</Button><Button primary disabled={!verified||note.trim().length<20||!checks.length||checks.some(x=>!x)||!(items[selected].evidence||[]).length} onClick={sign}>Confirm sign-off</Button></div></div></section></div>}</section>
}

function DeliverablesSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const [tab,setTab]=useState('Awaiting review');const [query,setQuery]=useState('');const [selected,setSelected]=useState<{startupId:string;deliverableId:string}|null>(null);const [note,setNote]=useState('');const [dueDate,setDueDate]=useState('');const [rating,setRating]=useState<'Does not meet'|'Meets'|'Exceeds'|'No rating'>('No rating');const [showAdd,setShowAdd]=useState(false);const [addForm,setAddForm]=useState({startupId:'',title:'',description:'',dueDate:'',format:'Document'});const verified=data.verifiedStatus==='Verified';const rows=data.startups.flatMap(s=>s.deliverables.map(d=>({...d,startupId:s.id,startupName:s.startupName,stage:s.stage})));const matches=(d:typeof rows[number])=>(!query||`${d.title} ${d.startupName}`.toLowerCase().includes(query.toLowerCase()))&&(tab==='All'||tab==='Awaiting review'&&d.status==='Submitted'||tab==='Requested by me'&&d.manual&&d.status!=='Accepted'||tab==='Accepted'&&d.status==='Accepted'||tab==='Changes requested'&&d.status==='Changes requested');const list=rows.filter(matches).sort((a,b)=>new Date(a.submittedAt||a.dueDate||'').getTime()-new Date(b.submittedAt||b.dueDate||'').getTime());const item=selected?data.startups.find(s=>s.id===selected.startupId)?.deliverables.find(d=>d.id===selected.deliverableId):undefined;const update=(patch:Partial<MentorDeliverable>)=>selected&&setData(d=>({...d,startups:d.startups.map(s=>s.id===selected.startupId?{...s,deliverables:s.deliverables.map(x=>x.id===selected.deliverableId?{...x,...patch}:x)}:s)}));const decide=(status:MentorDeliverable['status'])=>{if(status==='Changes requested'&&note.trim().length<20){notify('A change request note of at least 20 characters is required.');return}update({status,feedback:note,rating:rating==='No rating'?undefined:rating});setSelected(null);notify(`Deliverable marked ${status} in the local record; the startup was not notified.`)};const create=(e:FormEvent)=>{e.preventDefault();if(!addForm.title.trim()||!addForm.dueDate)return;setData(d=>({...d,startups:d.startups.map(s=>s.id===addForm.startupId?{...s,deliverables:[{id:rid('deliverable'),title:addForm.title.trim(),description:addForm.description,dueDate:addForm.dueDate,owner:'Startup owner',status:'To do',feedback:'',manual:true,expectedFormat:addForm.format},...s.deliverables]}:s)}));setShowAdd(false);notify('Deliverable request saved locally; no startup task was created.')};return <section id="mentor-deliverables" className={styles.rollSection}><SectionHeader title="Deliverables review" subtitle="A single queue for work shared by startups in your mentorships."><Button disabled={!verified||!data.startups.some(s=>s.status==='Active')} onClick={()=>setShowAdd(true)}><Plus size={13}/> Add deliverable</Button></SectionHeader><Notice warning>{verified?'Task synchronization and notifications are disconnected.':'Your mentor profile is under review. Deliverable decisions are disabled.'}</Notice><div className={styles.stats}>{[['Awaiting review',rows.filter(d=>d.status==='Submitted').length],['Overdue',rows.filter(d=>new Date(d.dueDate)<new Date()&&!['Accepted'].includes(d.status)).length],['Accepted this month',rows.filter(d=>d.status==='Accepted').length],['Average review time','—']].map(r=><div key={String(r[0])}><span>{r[0]}</span><strong>{r[1]}</strong></div>)}</div><div className={styles.toolbar}><nav className={styles.tabs}>{['Awaiting review','Requested by me','Accepted','Changes requested','All'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search deliverables"/></label></div><div className={styles.tableWrap}><table><thead><tr>{['Deliverable','Startup','Due date','Submitted','Status','Owner','Actions'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{list.map(d=><tr key={d.id}><td>{d.title}<small>{d.description||'No description'} · {d.expectedFormat||'Format not specified'}</small></td><td>{d.startupName} · {d.stage}</td><td>{fmt(d.dueDate)}</td><td>{d.submittedAt?fmt(d.submittedAt):'Not submitted'}</td><td><Status value={d.status}/></td><td>{d.owner}</td><td><Button onClick={()=>{setSelected({startupId:d.startupId,deliverableId:d.id});setNote(d.feedback||'');setDueDate('');setRating(d.rating||'No rating')}}>Review</Button><Link className={styles.textLink} href={`/mentor/startups/${d.startupId}`}>Workspace</Link></td></tr>)}</tbody></table></div>{!list.length&&<Empty title={tab==='Awaiting review'?"You're all caught up.":`No ${tab.toLowerCase()} deliverables.`} detail="No deliverable submissions are shared with this mentor. Startup tasks are not fetched without access." action="Open My Startups" href="#mentor-startups"/>}{selected&&item&&<div className={styles.modal}><section role="dialog" aria-modal="true" aria-labelledby="deliverable-review-title"><header><div><span className={styles.sectionKicker}>{data.startups.find(s=>s.id===selected.startupId)?.startupName}</span><h3 id="deliverable-review-title">{item.title}</h3></div><button className={styles.iconButton} onClick={()=>setSelected(null)} aria-label="Close"><X size={16}/></button></header><div className={styles.modalBody}><Notice warning>Submission content and file previews aren't connected. Review only data explicitly shared by the startup.</Notice><p><b>Description:</b> {item.description||'Not provided'}</p><p><b>Expected format:</b> {item.expectedFormat||'Not set'} · <b>Due:</b> {fmt(item.dueDate)}</p><p><b>Submission:</b> {item.submissionText||'No shared file or link.'}</p><Field label="Review note"><textarea maxLength={1000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Feedback to the startup"/></Field><Field label="Rating"><select value={rating} onChange={e=>setRating(e.target.value as typeof rating)}><option>No rating</option><option>Does not meet</option><option>Meets</option><option>Exceeds</option></select></Field><Field label="New due date (optional)"><input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></Field><p className={styles.caption}>Accepting or requesting changes would normally update the startup's task and notify them; this is a local-only record.</p><div className={styles.inlineActions}><Button onClick={()=>setSelected(null)}>Close</Button><Button disabled>Mark as seen</Button><Button disabled={!verified||note.trim().length<20} onClick={()=>decide('Changes requested')}>Request changes</Button><Button primary disabled={!verified} onClick={()=>decide('Accepted')}>Accept</Button></div></div></section></div>}{showAdd&&<div className={styles.modal}><section role="dialog" aria-modal="true" aria-label="Add deliverable"><header><h3>Request a deliverable</h3><button className={styles.iconButton} onClick={()=>setShowAdd(false)} aria-label="Close"><X size={16}/></button></header><form className={styles.modalBody} onSubmit={create}><Notice>Local proposal only. No task is created or sent to a startup.</Notice><Field label="Startup"><select required value={addForm.startupId} onChange={e=>setAddForm({...addForm,startupId:e.target.value})}><option value="">Select active mentorship</option>{data.startups.filter(s=>s.status==='Active').map(s=><option key={s.id} value={s.id}>{s.startupName}</option>)}</select></Field><Field label="Goal"><select><option>Choose a shared goal (not connected)</option></select></Field><Field label="Title"><input required value={addForm.title} onChange={e=>setAddForm({...addForm,title:e.target.value})}/></Field><Field label="Description"><textarea value={addForm.description} onChange={e=>setAddForm({...addForm,description:e.target.value})}/></Field><Field label="Expected format"><select value={addForm.format} onChange={e=>setAddForm({...addForm,format:e.target.value})}>{['Document','Link','Spreadsheet','Other'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Due date"><input required type="date" min={new Date().toISOString().slice(0,10)} value={addForm.dueDate} onChange={e=>setAddForm({...addForm,dueDate:e.target.value})}/></Field><footer><Button onClick={()=>setShowAdd(false)}>Cancel</Button><Button primary disabled={!verified} >Save local request</Button></footer></form></section></div>}</section>}

function EarningsSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const [tab,setTab]=useState('Overview');const [range,setRange]=useState('This month');const [selected,setSelected]=useState<string|null>(null);const [tableView,setTableView]=useState(false);const payments=data.payments;const paid=payments.filter(p=>p.status==='Paid');const pending=payments.filter(p=>p.status==='Pending'||p.status==='Processing');const paidNet=paid.reduce((n,p)=>n+p.net,0);const pendingNet=pending.reduce((n,p)=>n+p.net,0);const current=selected?payments.find(p=>p.id===selected):undefined;const exportCsv=()=>{const rows=[['Date','Startup','Item','Gross','Commission','Tax','Net','Status'],...payments.map(p=>[p.date,p.startupName,p.item,p.gross,p.gross*p.commissionPercent/100,p.tax,p.net,p.status])];const blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='mentor-payments-local.csv';a.click();URL.revokeObjectURL(u)};return <section id="mentor-earnings" className={styles.rollSection}><SectionHeader title="Earnings and payouts" subtitle="See your own session fees, payouts and tax records. Billing and payout providers are not connected."><label className={styles.field}>Date range<select value={range} onChange={e=>setRange(e.target.value)}><option>This month</option><option>Last 3 months</option><option>This financial year</option><option>Custom</option></select></label><Button onClick={exportCsv} disabled={!payments.length}><Download size={12}/> Export CSV</Button></SectionHeader><Notice warning>Your mentor profile is under review. Earnings, agreements and payout actions are unavailable until approval. No bank details or financial records are stored here.</Notice><nav className={styles.tabs}>{['Overview','Payments','Payouts','Invoices and tax','Payout settings'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav>{tab==='Overview'?<><div className={styles.kpis}>{[['Earned this month',paidNet?moneyINR(paidNet):'—','From paid local records'],['Pending',pendingNet?moneyINR(pendingNet):'—','Payment provider not connected'],['Paid out this financial year','—','Payout records unavailable'],['Next payout','Not scheduled','Payout provider unavailable']].map(x=><div key={String(x[0])}><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</div><div className={styles.twoColumn}><main className={styles.stack}><Card title="Earnings over time" subtitle="Net or gross amounts by month · no payment data is connected."><div className={styles.chartEmpty}><Activity size={20}/><strong>No earnings data</strong><small>Payment-provider sync has not supplied any records.</small></div><div className={styles.inlineActions}><Button onClick={()=>setTableView(!tableView)}>{tableView?'Chart view':'View as table'}</Button><span className={styles.dataSource}>Source: payment provider · unavailable</span></div>{tableView&&<div className={styles.tableWrap}><table><thead><tr><th>Month</th><th>Gross</th><th>Net</th></tr></thead><tbody><tr><td>No data</td><td>—</td><td>—</td></tr></tbody></table></div>}</Card><div className={styles.twoColumn}><Card title="Earnings by startup"><Empty title="No paid sessions." detail="No startup-level earnings records are available."/></Card><Card title="Sessions vs earnings"><Empty title="No linked billing data." detail="Session and payment records are disconnected."/></Card></div><Card title="Fee type mix"><p className={styles.emptyText}>Per-session, packages and other fee data are not connected. Equity or advisory terms are listed in Agreements, never treated as income here.</p></Card></main><aside className={styles.stack}><Card title="Next payout"><div className={styles.verifyCard}><LockKeyhole size={15}/><span><strong>Payout method missing</strong><small>No payout method can be added securely in this prototype.</small></span></div><p className={styles.emptyText}>Amount and date: Not available</p><Button disabled>Add payout method</Button><Link className={styles.textLink} href="#mentor-earnings">View payout settings</Link></Card><Card title="Needs your attention"><p className={styles.emptyText}>No connected payout, dispute or tax information.</p></Card><Card title="How payouts work"><p className={styles.emptyText}>Release timing, platform commission and minimum payout are set by the platform but are not available in this demo.</p><Button onClick={()=>notify('Payout policy is not connected.')}>Payout policy</Button></Card></aside></div></>:tab==='Payments'?<Card title="Payments" subtitle="Fees, commission and net amounts appear only when synced from billing."><div className={styles.tableWrap}><table><thead><tr>{['Date','Startup','Item','Gross','Commission','Tax','Net','Status','Receipt'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{payments.map(p=><tr key={p.id} onClick={()=>setSelected(p.id)}><td>{fmt(p.date)}</td><td>{p.startupName}</td><td>{p.item}</td><td>{moneyINR(p.gross)}</td><td>{moneyINR(p.gross*p.commissionPercent/100)} ({p.commissionPercent}%)</td><td>{moneyINR(p.tax)}</td><td><strong>{moneyINR(p.net)}</strong></td><td><Status value={p.status}/></td><td><Button disabled>Download</Button></td></tr>)}</tbody></table></div>{!payments.length&&<Empty title="No payments yet." detail="Your first paid session will appear when a payment provider is connected." action="View sessions" href="/mentor/sessions"/>}</Card>:tab==='Payouts'?<Card title="Payouts" subtitle="No payout schedule or payout provider is connected."><div className={styles.tableWrap}><table><thead><tr>{['Payout ID','Date','Amount','Method','Status','Payments included','Statement'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody><tr><td colSpan={7}>No payout records.</td></tr></tbody></table></div><Notice>Payout schedule, arrival dates, references and statements are not available.</Notice><Button disabled>Request payout · re-auth unavailable</Button></Card>:tab==='Invoices and tax'?<div className={styles.twoColumn}><Card title="Invoices"><Empty title="No invoices." detail="Invoice issuer, numbering, taxes and PDF generation are not connected."/></Card><Card title="Tax documents"><Empty title="No tax documents." detail="Annual statements and tax-deduction certificates are not available."/><p className={styles.legal}>The platform may provide records. It does not give tax advice. Confirm income tax, GST or TDS obligations with an accountant.</p></Card></div>:<div className={styles.twoColumn}><Card title="Payout method"><div className={styles.verifyCard}><LockKeyhole size={15}/><span><strong>No payout method saved</strong><small>Bank details are intentionally not collected or stored in this prototype.</small></span></div><Button disabled>Set up payout method · re-authentication required</Button><small className={styles.caption}>Never enter account details here until the secure billing integration is available.</small></Card><Card title="Payout preferences"><Field label="Schedule"><select disabled value={data.payoutPreferences.schedule}><option>Platform schedule</option><option>Monthly</option><option>Twice monthly</option></select></Field><Field label="Minimum payout (₹)"><input type="number" disabled value={data.payoutPreferences.minimumPayout}/></Field><Field label="Currency"><select value={data.payoutPreferences.currency} onChange={e=>setData(d=>({...d,payoutPreferences:{...d.payoutPreferences,currency:e.target.value}}))}><option>INR</option><option>USD</option></select></Field><label className={styles.checkLabel}><input type="checkbox" checked={data.payoutPreferences.notifications} onChange={e=>setData(d=>({...d,payoutPreferences:{...d.payoutPreferences,notifications:e.target.checked}}))}/> Payment notifications preference</label><small className={styles.caption}>Local preference only; no payouts or security alerts are configured.</small></Card></div>}{current&&<div className={styles.modal}><section role="dialog" aria-modal="true" aria-label="Payment breakdown"><header><h3>Payment detail · {current.item}</h3><button className={styles.iconButton} onClick={()=>setSelected(null)}><X size={15}/></button></header><div className={styles.modalBody}><AmountBreakdown payment={current}/><p className={styles.emptyText}>Agreement and session links are unavailable. Timeline: provider record not connected.</p><Button disabled>Report an issue · not connected</Button></div></section></div>}</section>}
function moneyINR(n:number){return `₹${new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(n||0)}`}
function AmountBreakdown({payment}:{payment:Pick<MentorRoleData['payments'][number],'gross'|'commissionPercent'|'tax'|'net'>}){return <div className={styles.amountBreakdown}><div><span>Session fee · gross</span><strong>{moneyINR(payment.gross)}</strong></div><div><span>Platform commission · {payment.commissionPercent}%</span><strong>−{moneyINR(payment.gross*payment.commissionPercent/100)}</strong></div><div><span>Tax</span><strong>{moneyINR(payment.tax)}</strong></div><div><b>Net to you</b><strong>{moneyINR(payment.net)}</strong></div></div>}
function AgreementsSection({data}:{data:MentorRoleData}){const [tab,setTab]=useState('Active');const [query,setQuery]=useState('');const rows=data.agreements.filter(a=>`${a.startupName} ${a.feeModel}`.toLowerCase().includes(query.toLowerCase())).filter(a=>tab==='All'||tab==='Active'&&a.status==='Active'||tab==='Awaiting you'&&['Proposed','Amended'].includes(a.status)||tab==='Proposed by you'&&a.status==='Proposed'||tab==='Ended'&&a.status==='Ended');return <section id="mentor-agreements" className={styles.rollSection}><SectionHeader title="Agreements" subtitle="Recorded fee, equity and advisory terms for your mentorships."><Button disabled>Create agreement template</Button></SectionHeader><Notice warning>Agreement storage, signatures, legal version history and payment links are not connected. This page shows no fabricated terms.</Notice><div className={styles.toolbar}><nav className={styles.tabs}>{['Active','Awaiting you','Proposed by you','Ended','All'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search startup"/></label></div>{rows.length?<div className={styles.tableWrap}><table><thead><tr><th>Startup</th><th>Type</th><th>Key terms</th><th>Equity/advisory</th><th>Start</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map(a=><tr key={a.id}><td>{a.startupName}</td><td>{a.feeModel}</td><td>{a.feeModel==='Free'?'No fee':`${moneyINR(a.rate)} · ${a.cadence}`}</td><td>{a.equityShare||'None recorded'}</td><td>{fmt(a.startDate)}</td><td><Status value={a.status}/></td><td><Link className={styles.textLink} href={`/mentor/agreements/${a.id}`}>Open</Link></td></tr>)}</tbody></table></div>:<Empty title="No agreements yet." detail="Agreements appear after a verified mentorship creates a recorded agreement. Nothing is self-reported as active." action="View requests" href="/mentor/requests"/>}<small className={styles.caption}>Only agreements belonging to this mentor should appear. This local workspace contains none.</small></section>}
function AgreementDetailSection({data,agreementId,notify}:{data:MentorRoleData;agreementId?:string;notify:(s:string)=>void}){const agreement=data.agreements.find(a=>a.id===agreementId);if(!agreement)return <section id="mentor-agreement-detail" className={styles.rollSection}><SectionHeader title="Agreement detail" subtitle="Agreement access is restricted to records where you are a party."/><Notice warning>{agreementId?'Agreement unavailable. No record was loaded for this ID.':'Open an agreement from the Agreements list to review its terms.'}</Notice><Empty title={agreementId?'Agreement not found.':'No agreement selected.'} detail="No terms or financial information are returned for unknown agreement IDs." action="Agreements" href="/mentor/agreements"/></section>;return <section id="mentor-agreement-detail" className={styles.rollSection}><SectionHeader title={`${agreement.startupName} · Agreement`} subtitle={`Version ${agreement.version} · ${agreement.status} · local record`}><Link className={styles.secondary} href={`/mentor/startups/${agreement.startupId}`}>Workspace</Link><Button disabled>Accept · re-auth unavailable</Button><Button disabled>Propose change</Button><Button disabled>Request to end</Button></SectionHeader><Notice warning>Terms are not executed. The platform records terms but does not provide legal advice.</Notice><div className={styles.twoColumn}><main className={styles.stack}><Card title="Summary"><div className={styles.infoGrid}>{[['Status',agreement.status],['Fee model',agreement.feeModel],['Rate',moneyINR(agreement.rate)],['Cadence',agreement.cadence],['Duration',agreement.duration],['Commission',`${agreement.commissionPercent}%`],['Start date',fmt(agreement.startDate)],['End date',fmt(agreement.endDate)]].map(x=><div key={x[0]}><small>{x[0]}</small><strong>{x[1]}</strong></div>)}</div></Card><Card title="Fees and payments"><AmountBreakdown payment={{gross:agreement.rate,commissionPercent:agreement.commissionPercent,tax:0,net:agreement.rate*(1-agreement.commissionPercent/100)}}/><p className={styles.emptyText}>Payment timing and cancellation rules are not available.</p></Card><Card title="Equity or advisory share"><p>{agreement.equityType||'None recorded'} · {agreement.equityShare||'No share recorded'}</p><p>{agreement.vesting||'Vesting terms not set'}</p><p className={styles.legal}>Equity terms have legal and tax consequences. Review them with a lawyer. The platform records terms and does not give legal advice.</p></Card><Card title="Scope and responsibilities"><p>{agreement.scope||'Scope not entered.'}</p></Card><Card title="Confidentiality and conduct"><Notice>Conflict of interest and confidentiality terms are not connected. Never provide sign-off in exchange for payment or another benefit.</Notice></Card><Card title="Version history">{agreement.versions.map(v=><div className={styles.deliverableRow} key={v.version}><span><strong>v{v.version} · {v.proposedBy}</strong><small>{fmt(v.date)} · {v.summary}</small></span><span>{v.active?'Currently active':'Previous'}</span><Button disabled>Compare</Button></div>)}</Card></main><aside className={styles.stack}><Card title="Status and next action"><Status value={agreement.status}/><p className={styles.emptyText}>Legal acceptance and notifications are not connected.</p></Card><Card title="Linked records"><p>{agreement.startupName}</p><p>Earnings under agreement: not connected</p><Link className={styles.textLink} href={`/mentor/earnings`}>Open earnings</Link></Card><Card title="Need help"><Button onClick={()=>notify('Agreement guide and support are not connected.')}>Agreement guide</Button></Card></aside></div></section>}
function ImpactSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const [tab,setTab]=useState('My impact');const [sort,setSort]=useState('Newest');const completed=data.startups.filter(s=>s.status==='Completed');const sessions=data.startups.flatMap(s=>s.sessions).filter(s=>s.status==='Completed');const signed=data.startups.flatMap(s=>s.readinessItems).filter(i=>i.status==='Signed off').length;const readyCount=completed.filter(s=>s.readinessItems.length&&s.readinessItems.every(i=>i.status==='Signed off')).length;const publicVisible=false;const publishedReviews=data.reviews.filter(r=>r.status==='Published');const avg=publishedReviews.length?publishedReviews.reduce((a,r)=>a+r.rating,0)/publishedReviews.length:0;const consentIds=new Set(data.impactStartupIds);return <section id="mentor-impact" className={styles.rollSection}><SectionHeader title="Impact and reviews" subtitle="A verified, consent-based record of your mentoring outcomes."><span className={styles.dataSource}>Public record: {publicVisible?'Visible':'Hidden'}</span></SectionHeader><Notice warning>Impact, reviews, startup consent and public profile verification are not connected. The page does not publish or invent outcome metrics.</Notice><nav className={styles.tabs}>{['My impact','Reviews','Public view'].map(t=><button key={t} onClick={()=>setTab(t)} className={tab===t?styles.tabActive:styles.tab}>{t}</button>)}</nav>{tab==='My impact'?<><div className={styles.kpis}>{[['Startups mentored',data.startups.length||'—',`${data.startups.filter(s=>s.status==='Active').length} active local records`],['Sessions delivered',sessions.length||'—','Completed local sessions'],['Sign-offs granted',signed||'—','Local records only'],['Investment Ready badges helped earn',readyCount||'—','Badge service not connected']].map(x=><div key={String(x[0])}><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</div><div className={styles.twoColumn}><main className={styles.stack}><Card title="Startup outcomes" subtitle="Only outcomes with startup consent belong in the public record.">{completed.length?completed.map(s=><article className={styles.outcomeRow} key={s.id}><strong>{s.startupName}</strong><small>Stage at start: not recorded · Stage now: {s.stage}</small><small>Readiness change: not calculated · badge: not verified</small><label className={styles.checkLabel}><input type="checkbox" checked={consentIds.has(s.id)} disabled={data.verifiedStatus!=='Verified'} onChange={e=>setData(d=>({...d,impactStartupIds:e.target.checked?[...d.impactStartupIds,s.id]:d.impactStartupIds.filter(id=>id!==s.id)}))}/> Select for public view (startup consent is still required)</label></article>):<Empty title="No verified startup outcomes yet." detail="Verified mentorships and startup consent are required before impact can be calculated or published."/>}</Card><Card title="Readiness progress over time"><div className={styles.chartEmpty}><Activity size={20}/><strong>No verified readiness time series.</strong><small>Correlation, not proof of cause. No scores are inferred.</small></div><Button onClick={()=>notify('No data table is available until readiness history is connected.')}>View as table</Button></Card><div className={styles.twoColumn}><Card title="Stage progression"><Empty title="Not enough records." detail="Stage changes during mentorship are not connected."/></Card><Card title="Time and responsiveness"><Empty title="No verified activity data." detail="Attendance, review and response-time measures aren't connected."/></Card></div><Card title="Expertise tags earned"><p className={styles.emptyText}>System-awarded expertise tags require verified sign-offs and reviews. None are available.</p></Card><Card title="Milestone badges"><p className={styles.emptyText}>No badges have been verified or issued.</p></Card><Card title="Startup testimonials"><Empty title="No opt-in testimonials." detail="Testimonials require startup consent and a verified session."/></Card></main><aside className={styles.stack}><Card title="Public visibility"><p className={styles.emptyText}>Public impact record: {publicVisible?'Visible':'Hidden'} · no public profile publishing service.</p><label className={styles.checkLabel}><input type="checkbox" checked={false} disabled/> Make verified impact visible</label><Button disabled={!publicVisible}>Open public profile</Button><Button disabled>Download impact summary · PDF unavailable</Button></Card><Card title="Outcome note"><p className={styles.emptyText}>Outcomes reflect many factors. Correlation is not proof that mentoring caused an outcome.</p></Card></aside></div></>:tab==='Reviews'?<><Card title="Review summary"><div className={styles.reviewSummary}><strong>{avg?avg.toFixed(1):'—'}</strong><span>{avg?'★'.repeat(Math.round(avg)):'No rating data'}<small>{publishedReviews.length} verified reviews · response rate not calculated</small></span></div>{[5,4,3,2,1].map(n=><div className={styles.reviewBar} key={n}><span>{n} stars</span><Progress value={publishedReviews.length?publishedReviews.filter(r=>r.rating===n).length/publishedReviews.length*100:0}/><small>{publishedReviews.filter(r=>r.rating===n).length}</small></div>)}</Card><Card title="Public reviews"><div className={styles.toolbar}><Field label="Sort"><select value={sort} onChange={e=>setSort(e.target.value)}><option>Newest</option><option>Highest</option><option>Lowest</option></select></Field></div>{publishedReviews.length?publishedReviews.map(r=><article className={styles.reviewCard} key={r.id}><div><strong>{r.anonymous?'Anonymous startup':r.startupName}</strong><small>{fmt(r.date)} · {r.rating} / 5 · {r.verifiedSession?'Verified session':'Unverified'}</small></div><p>{r.body}</p>{r.publicReply?<div className={styles.replyBox}>Your reply: {r.publicReply}</div>:<Button disabled>Reply publicly</Button>}<Button onClick={()=>notify('Moderation report service is not connected.')}>Report review</Button></article>):<Empty title="No verified reviews yet." detail="Reviews appear after a completed session and startup submission. Reviews cannot be purchased or edited."/>}</Card><Card title="Private feedback"><p className={styles.emptyText}>No private feedback is available.</p></Card><Card title="Request a review"><p className={styles.emptyText}>No completed mentorships without a review are available. Review requests are limited and never incentivized.</p><Button disabled>Request review</Button></Card></>:<><Card title="Public impact preview"><div className={styles.publicPreview}><span className={styles.eyebrow}>Mentor profile · private preview</span><h3>{data.privateProfile.name}</h3><Notice>Public impact is hidden. Platform verification and startup consent are unavailable; no identities, outcomes or metrics are shown.</Notice><p className={styles.emptyText}>No consented impact data can be displayed.</p></div><Button onClick={()=>setTab('My impact')}>Edit visibility</Button><Button disabled={!publicVisible}>Open public profile</Button></Card></>}</section>}
function EventsSection({data,notify}:{data:MentorRoleData;notify:(s:string)=>void}){const [tab,setTab]=useState('Upcoming');const [query,setQuery]=useState('');const events=data.events.filter(e=>e.title.toLowerCase().includes(query.toLowerCase()));const list=events.filter(e=>tab==='Upcoming'?e.access!=='Past':tab==='My registrations'?false:tab==='Invitations'?false:e.access==='Past');return <section id="mentor-events" className={styles.rollSection}><SectionHeader title="Investor events" subtitle="Priority access to events where mentors and startups meet investors."><Button disabled onClick={()=>notify('Event notifications are not connected.')}>Notify me when events open</Button></SectionHeader><Notice warning>Event catalog, eligibility, registrations, invitations and investor attendance are not connected. No events are fabricated.</Notice><div className={styles.toolbar}><nav className={styles.tabs}>{['Upcoming','My registrations','Invitations','Past'].map(t=><button key={t} className={tab===t?styles.tabActive:styles.tab} onClick={()=>setTab(t)}>{t}</button>)}</nav><label className={styles.search}><Search size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search events"/></label><select><option>All types</option><option>Demo day</option><option>Pitch evening</option><option>Investor office hours</option></select></div><div className={styles.eventFeature}><span className={styles.goldRule}/><div><span className={styles.sectionKicker}>Featured event</span><strong>No upcoming event data</strong><small>Priority access windows and event seats aren't connected.</small></div><Button disabled>View</Button></div>{list.length?list.map(e=><article className={styles.eventCard} key={e.id}><Link href={`/mentor/events/${e.id}`}><strong>{e.title}</strong></Link><small>{fmt(e.date)} · {e.timezone}</small><small>{e.format} · {e.location||'Location not set'} · Hosted by {e.host}</small><small>{e.focus} · {e.stages.join(', ')}</small><div className={styles.inlineActions}><Status value={e.access}/><Button disabled>Register</Button><Link className={styles.secondary} href={`/mentor/events/${e.id}`}>View details</Link></div></article>):<Empty title={tab==='Past'?'No past events.':'No upcoming events right now.'} detail="We'll show events when an organizer publishes them. Event registration and notifications are not connected."/>}<p className={styles.disclaimer}><Info size={12}/> The platform introduces parties and is not a broker or adviser unless licensed.</p></section>}
function EventDetailSection({data,eventId,notify}:{data:MentorRoleData;eventId?:string;notify:(s:string)=>void}){const event=data.events.find(e=>e.id===eventId);if(!event)return <section id="mentor-event-detail" className={styles.rollSection}><SectionHeader title="Investor event detail" subtitle="Event details are available only for published events."/><Notice warning>{eventId?'No event record was found.':'Open an event from the Investor Events list.'} No event service is connected.</Notice><Empty title={eventId?'Event not found.':'No event selected.'} detail="No attendance or investor list is being displayed." action="View investor events" href="/mentor/events"/></section>;return <section id="mentor-event-detail" className={styles.rollSection}><SectionHeader title={event.title} subtitle={`${fmt(event.date)} · ${event.timezone} · ${event.format}`}><Link className={styles.secondary} href="/mentor/events">Events</Link><Button disabled>Register</Button></SectionHeader><Notice warning>Event registration and investor introductions are not connected. Do not treat this local event record as confirmed.</Notice><div className={styles.twoColumn}><main className={styles.stack}><Card title="About"><p>{event.description}</p><p>{event.host} · {event.location}</p></Card><Card title="Agenda"><Empty title="Agenda not published." detail="No agenda or speakers are available."/></Card><Card title="Who's attending"><Empty title="Attendee names are not available." detail="Only consented attendees could be shown after event integration."/></Card><Card title="Your startups at this event"><p className={styles.emptyText}>No application or recommendation data is connected.</p></Card><Card title="How mentors can take part"><p>Attend, join office hours, provide pitch coaching, or recommend a mentee only through a connected event workflow.</p><Button disabled onClick={()=>notify('Recommendation workflow not connected.')}>Recommend a startup</Button></Card><Card title="Logistics and documents"><p className={styles.emptyText}>Venue instructions, accessibility notes, conduct policy and event documents are not available.</p></Card></main><aside className={styles.stack}><Card title="Registration"><Status value={event.access}/><p className={styles.emptyText}>Registration status: not registered · integration not connected.</p><Button disabled>Register</Button><Button disabled>Add to calendar</Button></Card><Card title="Seats"><p className={styles.emptyText}>Seat count and waitlist status unavailable.</p></Card><Card title="Contact organizer"><Button onClick={()=>notify('Organizer contact service is not connected.')}>Contact organizer</Button><Button onClick={()=>notify('Event concern reporting is not connected.')}>Report a concern</Button></Card></aside></div></section>}
function MessagesSection({data}:{data:MentorRoleData}){return <section id="mentor-messages" className={styles.rollSection}><SectionHeader title="Messages" subtitle="Secure mentor-startup chat is not connected."/><Card title="Conversations">{data.startups.length?data.startups.map(s=><div className={styles.sessionRow} key={s.id}><MessageSquareText size={14}/><span><strong>{s.startupName}</strong><small>Conversation integration unavailable</small></span><Button disabled>Open</Button></div>):<Empty title="No messages." detail="Messages are available only for an assigned mentorship. No message history is being fetched." action="View startups" href="#mentor-startups"/>}</Card><Notice warning>No message has been sent. Private notes are never shown in this area.</Notice></section>}
function SettingsSection({data,setData,notify}:{data:MentorRoleData;setData:React.Dispatch<React.SetStateAction<MentorRoleData>>;notify:(s:string)=>void}){const update=(patch:Partial<MentorRoleData>)=>setData(d=>({...d,...patch}));return <section id="mentor-settings" className={styles.rollSection}><SectionHeader title="Mentor profile & settings" subtitle="Profile and availability preferences can be prepared while verification is pending."/><div className={styles.twoColumn}><main className={styles.stack}><Card title="Verification status"><div className={styles.verifyCard}><ShieldAlert size={18}/><span><strong>{data.verifiedStatus}</strong><small>Admin review and identity verification are not connected. Do not represent this profile as verified.</small></span></div><Button disabled>Contact support · not connected</Button></Card><Card title="Profile basics"><Field label="Display name"><input value={data.privateProfile.name} onChange={e=>update({privateProfile:{...data.privateProfile,name:e.target.value}})}/></Field><Field label="Headline"><input value={data.privateProfile.headline} onChange={e=>update({privateProfile:{...data.privateProfile,headline:e.target.value}})}/></Field><Field label="About your mentoring"><textarea maxLength={2000} rows={4} value={data.privateProfile.bio} onChange={e=>update({privateProfile:{...data.privateProfile,bio:e.target.value}})} placeholder="Prepare your profile. It is not published."/></Field><small className={styles.caption}>Saved locally · not a public or verified profile.</small></Card></main><aside className={styles.stack}><Card title="Availability and capacity"><Field label="Status"><select value={data.availability} onChange={e=>{update({availability:e.target.value as MentorRoleData['availability']});notify('Availability saved locally; not published.')}}><option>Accepting new startups</option><option>At capacity</option><option>Paused</option></select></Field><Field label="Capacity · 1–20"><input type="number" min="1" max="20" value={data.capacity} onChange={e=>update({capacity:Math.max(data.startups.filter(s=>s.status==='Active').length,Math.min(20,+e.target.value||1))})}/></Field><small className={styles.caption}>Availability can be edited; requests and matching are disconnected.</small></Card><Card title="Privacy"><p className={styles.emptyText}>Startup-specific data remains hidden until the startup explicitly shares it. Access revocation and audit logs are not connected.</p></Card></aside></div></section>}
